// Cloudflare Pages Function -- /api/project-override
// PER-SECTION MANUAL OVERRIDES for a project record (the office project-record
// view). Every project record renders 11 collapsible "schema cards" (General
// Info, PF Team, Contract Info, Engineering & Design, Project Safety, Site
// Readiness, Equipment, Material, QA/QC, Financials, Project Closeout). The base
// values come from STATIC synced JS (data/project-records.js, with POET falling
// back to data/project-record-poet.js). Those files are regenerated by the sync
// pipeline, so a user CANNOT edit them in place. This endpoint is the SEPARATE
// override store: a user with office access can manually enter/edit any field in
// any section and that value is stored here in KV, MERGED on top of the synced
// record at render time (the override ALWAYS wins). Overrides survive reload and
// survive a future data sync, and are visible to the whole office.
//
// WHAT IT STORES
//   project_override_v1:<num>  ->  JSON {
//     num,                                  // the project number this belongs to
//     sections: { <sectionKey>: { <fieldLabel>: <stringValue>, ... }, ... },
//     _meta: { updatedBy, updatedAt }       // last writer + when (server-set)
//   }
//   sectionKey is one of the 11 stable card keys (general, pfTeam, contract,
//   engineering, safety, siteReadiness, equipment, material, qaqc, financials,
//   closeout). fieldLabel is the field's display label (the same label the
//   renderer shows). Values are STRINGS (text/number/date all stored as text;
//   the client formats). ZERO financial computation happens here -- this is a
//   plain string overlay keyed by (section, label). Money strings a user types
//   are stored verbatim as text; nothing is summed, priced, or derived.
//
// KV KEY: env.PF_SCHEDULE :: 'project_override_v1:<num>'  (one key per project).
//
// RBAC (the critical part):
//   - Behind the auth gate (functions/_middleware.js): no session -> 401.
//   - FINANCIALS area (the office): requireArea(session, 'financials') on GET and
//     POST. financials = admin/partner/business_dev -- the SAME roles that can
//     view/edit the project record. field_ops is BLOCKED (can neither read nor
//     write overrides), even by direct URL. /api/project-override -> 'financials'
//     in areaForPath (defense-in-depth with this handler's requireArea).
//   - WRITE hardening (mirrors daily-report/pm-project): body cap, strict JSON ->
//     400, section validated against the fixed key list, fields rebuilt +
//     length-capped, angle brackets stripped, updatedBy/updatedAt set from the
//     SESSION (never client-supplied), no eval. Private no-store.
//   - FAIL CLOSED: if KV is not bound, POST returns 503 (the client keeps the
//     user in edit mode and shows an honest error -- it NEVER shows "saved").
//   - NO mail, NO outbound fetch.

import { requireArea } from '../lib/auth.js';

const KV_PREFIX = 'project_override_v1:';
const MAX_BODY_BYTES = 64 * 1024;   // an override for one section (many fields) fits easily
const MAX_LABEL = 200;              // a field label
const MAX_VALUE = 4000;             // a manually entered value (text/number/date)
const MAX_FIELDS_PER_SECTION = 200; // generous cap; a section has ~25 fields
const MAX_TOTAL_SECTIONS = 40;      // > the 11 cards, room to grow; bounds abuse

// ---- __crm reserved structured key (Brad 2026-08-11, CRM cascading selector) --
// The Design Professionals block gains a per-section CRM selection: for each firm
// section (Ground Improvement / Geotechnical / Civil / Structural / GC) the user
// picks a company from the master directory + checks which of that company's
// contacts belong on THIS project. That selection is stored under ONE reserved,
// object-valued key `__crm` INSIDE the `design_professionals` section:
//   sections.design_professionals.__crm = {
//     "<Section>": { company: "<name>", contactIds: ["C0005", ...] }, ...
//   }
// Every OTHER key in every section stays a plain string (the existing overlay).
// __crm is the SOLE exception, allowed under design_professionals AND general (the
// General Info card's Owner + General Contractor selectors — Brad 2026-08-11), and
// is STRICTLY validated (below) so the store can never be corrupted by a crafted
// object. It survives a normal per-field section save because the section merge
// (Object.assign(existing, fields)) preserves any key the editor omits. Under
// `general` the __crm object coexists with the flat Owner/GC string fields; the two
// firm keys used there are "Owner" and "GC".
const CRM_KEY = '__crm';
// __crm is allowed under these section keys ONLY. design_professionals hosts the
// engineering firm selectors (Ground Improvement / Geotechnical / Civil / Structural
// / GC engineering entry); general hosts the project OWNER and General Contractor
// selectors (Brad 2026-08-11: "same way you made companies/contacts populate, do the
// same with project owners and general contractors"). Both persist the identical
// { "<Section>": { company, contactIds[] } } shape validated by cleanCrm below; the
// Owner/GC selection lives beside the flat Owner/GC string fields under `general`
// (Object.assign merge preserves both). Any OTHER section rejects a __crm body (400).
// Brad 2026-08-11 (Project Contacts restructure): the new dedicated contact groups
// (Safety Consultant / Staking & Layout / Equipment Transport + Rental Equipment /
// Material Vendor(s) + Fuel Delivery) live in the Project Contacts section under
// EXISTING override keys (safety / siteReadiness / equipment / material) and each
// carries a cascading company->contacts CRM selector. So those four keys must accept a
// __crm body too. Same { "<Section>": { company, contactIds[] } } shape + validation.
// pfTeam added 2026-08-11: the PF Project Team group (Project Contacts #7) was converted
// from role-based plain cards to the same cascading company->contacts CRM selector as
// the other groups (Category "PF Team"), so its key must also accept a __crm body. Same
// { "<Section>": { company, contactIds[] } } shape + validation as every other CRM key.
const CRM_ALLOWED_SECTIONS = {
  design_professionals: 1, general: 1,
  pfTeam: 1,
  safety: 1, siteReadiness: 1, equipment: 1, material: 1,
};
const CRM_MAX_FIRMS = 12;            // >5 real firm sections, bounds abuse
const CRM_MAX_IDS = 40;              // contacts per firm on one project (generous)
const CRM_MAX_COMPANY = 200;         // a company name length cap
const CRM_MAX_SUBKEY = 60;           // a firm-section label length cap
const CRM_ID_RE = /^C\d+$/;          // contact id shape (C#### minted by /api/contacts)

// ---- __submittal_prereqs reserved structured key (Brad 2026-08-12) -----------
// The Engineering & Design > PF Design Submittal subsection gains a "GC prerequisites"
// checklist ABOVE its fields: the 7 items PF needs from the GC before starting the full
// Submittal Design. Each item carries a responsible party (name + email, for the reminder
// email) and a Date Received (filled = received). That per-item state is stored under ONE
// reserved, object-valued key `__submittal_prereqs` INSIDE the `engineering` section:
//   sections.engineering.__submittal_prereqs = {
//     items: { "<itemKey>": { responsible_name, responsible_email, date_received,
//                             required_for:{ submittal_design, staking_layout } }, ... }
//   }
// required_for (Brad 2026-08-12) = metadata booleans marking whether the item is needed
// for Submittal Design and/or Staking Layout. NOT part of the received-count.
// itemKey is a short stable slug the client mints per row (e.g. "struct_foundation_cad").
// Every OTHER key in the engineering section stays a plain string (the existing overlay).
// This is the SECOND reserved object key (alongside __crm) and rides the SAME merge:
// Object.assign(existing, fields) preserves it when a normal field save omits it, so
// editing the engineering tracking fields never wipes the checklist and vice-versa.
// STRICTLY validated (cleanPrereqs below); a malformed body fails the WHOLE save closed.
// Allowed ONLY under the `engineering` section (rejected 400 anywhere else).
const PREREQ_KEY = '__submittal_prereqs';
const PREREQ_ALLOWED_SECTIONS = { engineering: 1 };
const PREREQ_MAX_ITEMS = 40;         // 7 real items today; generous headroom, bounds abuse
const PREREQ_MAX_ITEMKEY = 60;       // an item slug length cap
const PREREQ_MAX_NAME = 200;         // responsible-party name cap
const PREREQ_MAX_EMAIL = 254;        // RFC max email length
const PREREQ_MAX_DATE = 40;          // a date string (ISO YYYY-MM-DD or MM/DD/YYYY)
const PREREQ_MAX_CID = 20;           // a directory contactId (C#### shape)

// Validate + normalize an incoming __submittal_prereqs object into a clean, bounded
// structure. Returns a SAFE object, or null if present-but-malformed (caller fails the
// whole save closed). Rules mirror cleanCrm's defensive posture:
//   - top-level must be a plain object; its `items` (if present) must be a plain object.
//   - each item value must be a plain object; responsible_name / responsible_email /
//     date_received are strings, length-capped and angle-bracket stripped (via s()).
//   - unknown item keys are length-capped; a bad email is DROPPED to '' (never rejects
//     the whole save — a name-only assignment is legitimate); NO email-format gate here
//     (the reminder endpoint validates format before it ever sends).
//   - bounded on item count; over the cap => reject (null) so nothing is silently lost.
function cleanPrereqs(input) {
  if (input == null) return { items: {} };            // absent => empty
  if (typeof input !== 'object' || Array.isArray(input)) return null; // present but not object => reject
  const itemsIn = (input.items && typeof input.items === 'object' && !Array.isArray(input.items))
    ? input.items : {};
  const keys = Object.keys(itemsIn);
  if (keys.length > PREREQ_MAX_ITEMS) return null;
  const items = {};
  for (const rawKey of keys) {
    const key = s(rawKey, PREREQ_MAX_ITEMKEY);
    if (!key) continue;
    const entry = itemsIn[rawKey];
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) return null;
    // required_for: metadata flags for what the item is needed for (Brad 2026-08-12).
    // Optional object; coerced to two strict booleans. Absent/malformed => both false
    // (never rejects the save — this is metadata, not a gate). Never part of the
    // received-count (that is date_received only).
    const rf = (entry.required_for && typeof entry.required_for === 'object' && !Array.isArray(entry.required_for))
      ? entry.required_for : {};
    // responsible_contact_id (Brad 2026-08-12): the tied directory contactId when the
    // responsible party was chosen from the project's contacts. Optional; validated to
    // the C#### shape (upper-cased) or dropped to '' (a bad/absent tie never rejects the
    // save — the name/email still persist so reminders work). Metadata, not a gate.
    const cidRaw = s(entry.responsible_contact_id, PREREQ_MAX_CID).toUpperCase();
    const responsibleCid = /^C\d+$/.test(cidRaw) ? cidRaw : '';
    items[key] = {
      responsible_contact_id: responsibleCid,
      responsible_name:  s(entry.responsible_name, PREREQ_MAX_NAME),
      responsible_email: s(entry.responsible_email, PREREQ_MAX_EMAIL),
      date_received:     s(entry.date_received, PREREQ_MAX_DATE),
      required_for: {
        submittal_design: rf.submittal_design === true,
        staking_layout:   rf.staking_layout === true,
      },
    };
  }
  return { items };
}

// ---- __submittal_cycles reserved structured key (Brad 2026-08-12, Stage 2) ----
// The PF Design Submittal workflow (the linear date chain + status) can go through
// MULTIPLE revision cycles: the Original submittal, then Rev1, Rev2, ... when the GC
// returns "Revise & Resubmit". Each cycle is a FULL copy of the Stage-1 workflow's
// MANUAL fields (the two computed dates are derived at render per cycle, never stored).
// The whole set is stored as ONE reserved, ARRAY-valued key `__submittal_cycles` INSIDE
// the `engineering` section:
//   sections.engineering.__submittal_cycles = [
//     { rev:0, prereqs_sent, actual_completion, pf_submits_gc, status },  // Original
//     { rev:1, prereqs_sent, actual_completion, pf_submits_gc, status },  // Rev1
//     ...
//   ]
// rev is a non-negative integer index (0 = Original). prereqs_sent / actual_completion /
// pf_submits_gc are date strings (ISO or MM/DD/YYYY); status is one of the 3 dropdown
// values (validated loosely as a capped string -- the client owns the option list; a
// free string never corrupts the store). This is the THIRD reserved key (alongside
// __crm and __submittal_prereqs) and rides the SAME merge: Object.assign(existing,
// fields) preserves it when a normal field save omits it, so editing the flat
// engineering fields never wipes the cycles and vice-versa. STRICTLY validated
// (cleanCycles below); a malformed body fails the WHOLE save closed. Allowed ONLY under
// the `engineering` section (rejected 400 anywhere else).
const CYCLES_KEY = '__submittal_cycles';
const CYCLES_ALLOWED_SECTIONS = { engineering: 1 };
const CYCLES_MAX = 60;               // Original + up to 59 revisions; bounds abuse
const CYCLES_MAX_DATE = 40;          // a date string (ISO YYYY-MM-DD or MM/DD/YYYY)
const CYCLES_MAX_STATUS = 60;        // a status dropdown value

// Validate + normalize an incoming __submittal_cycles ARRAY into a clean, bounded
// structure. Returns a SAFE array, or null if present-but-malformed (caller fails the
// whole save closed). Rules mirror cleanPrereqs' defensive posture:
//   - top-level must be an ARRAY; over the cap => reject (null) so nothing is silently
//     lost.
//   - each entry must be a plain object; prereqs_sent / actual_completion /
//     pf_submits_gc / status are strings, length-capped + angle-bracket stripped (s()).
//   - rev is coerced to a non-negative integer; if absent/invalid it is reassigned to
//     the entry's array index (rev is positional -- Original=0, Rev1=1, ...). This keeps
//     the stored rev honest even if a client omits it.
function cleanCycles(input) {
  if (input == null) return [];                        // absent => empty
  if (!Array.isArray(input)) return null;              // present but not an array => reject
  if (input.length > CYCLES_MAX) return null;
  const out = [];
  for (let i = 0; i < input.length; i++) {
    const entry = input[i];
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) return null;
    let rev = Number(entry.rev);
    if (!Number.isInteger(rev) || rev < 0) rev = i;    // positional fallback
    out.push({
      rev: rev,
      prereqs_sent:      s(entry.prereqs_sent, CYCLES_MAX_DATE),
      actual_completion: s(entry.actual_completion, CYCLES_MAX_DATE),
      pf_submits_gc:     s(entry.pf_submits_gc, CYCLES_MAX_DATE),
      status:            s(entry.status, CYCLES_MAX_STATUS),
      // shop_due_override (Brad 2026-08-12): the "Shop Drawings Due from Garbin" date is
      // auto-computed (prereqs_sent + 15 business days) but MANUALLY OVERRIDABLE when a
      // faster-than-3-week turnaround is agreed. A non-empty string here wins over the
      // computed value at render; empty => fall back to the computed date. Same date-string
      // treatment as the other date fields (trim + length cap; the client owns the format).
      // Backward-compatible: cycles saved before this field simply carry '' (absent => '').
      shop_due_override: s(entry.shop_due_override, CYCLES_MAX_DATE),
      // approved_submittal_date (Brad 2026-08-12): the date the submittal was returned +
      // approved from the GC. Only meaningful when status is Approved/Reviewed or AAN (the
      // client renders + prefills it conditionally); stored verbatim as a date string.
      // Same trim + length cap as the other date fields. Backward-compatible: absent => ''.
      approved_submittal_date: s(entry.approved_submittal_date, CYCLES_MAX_DATE),
    });
  }
  return out;
}

// ---- __site_elevations reserved structured key (Brad 2026-08-12) --------------
// The Engineering & Design section gains a "Site Grade Elevations" subsection directly
// BELOW the PF Design Submittal workflow: per-project site grade + finish floor elevation
// capture for MULTIPLE named areas/buildings. The whole list is stored as ONE reserved,
// ARRAY-valued key `__site_elevations` INSIDE the `engineering` section:
//   sections.engineering.__site_elevations = [
//     { id, area, gradeElev, ffe }, ...
//   ]
// id is a stable client-minted key (like the CRM contact ids / cycle rows). area /
// gradeElev / ffe are FREE-TEXT strings (not numeric -- users type units/decimals like
// "612.50" or "612.5 ft"). This is the FOURTH reserved key (alongside __crm,
// __submittal_prereqs, __submittal_cycles) and rides the SAME merge: Object.assign(
// existing, fields) preserves it when a normal flat field save omits it, so editing the
// flat engineering fields never wipes the elevations and vice-versa. STRICTLY validated
// (cleanSiteElevations below); a malformed body fails the WHOLE save closed. Allowed ONLY
// under the `engineering` section (rejected 400 anywhere else). MANUAL-ENTRY only -- no
// external sync feed writes this key.
const SITE_ELEV_KEY = '__site_elevations';
const SITE_ELEV_ALLOWED_SECTIONS = { engineering: 1 };
const SITE_ELEV_MAX = 100;            // named areas/buildings on one project; bounds abuse
const SITE_ELEV_MAX_ID = 60;          // a client-minted row id length cap
const SITE_ELEV_MAX_AREA = 200;       // an area/building name cap
const SITE_ELEV_MAX_VALUE = 200;      // a free-text elevation value (e.g. "612.50 ft")

// Validate + normalize an incoming __site_elevations ARRAY into a clean, bounded
// structure. Returns a SAFE array, or null if present-but-malformed (caller fails the
// whole save closed). Rules mirror cleanCycles' defensive posture:
//   - top-level must be an ARRAY; over the cap => reject (null) so nothing is silently
//     lost.
//   - each entry must be a plain object; area / gradeElev / ffe are strings, trimmed,
//     length-capped, and angle-bracket stripped (via s()).
//   - id is a client-minted stable key; kept if it is a non-empty capped string, else a
//     positional fallback ("area-<index>") is minted so every row always has a stable id.
//   - unknown keys on an entry are DROPPED (only id/area/gradeElev/ffe survive).
function cleanSiteElevations(input) {
  if (input == null) return [];                        // absent => empty
  if (!Array.isArray(input)) return null;              // present but not an array => reject
  if (input.length > SITE_ELEV_MAX) return null;
  const out = [];
  for (let i = 0; i < input.length; i++) {
    const entry = input[i];
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) return null;
    let id = s(entry.id, SITE_ELEV_MAX_ID).trim();
    if (!id) id = 'area-' + i;                          // positional fallback: always have a stable id
    out.push({
      id: id,
      area:      s(entry.area, SITE_ELEV_MAX_AREA).trim(),
      gradeElev: s(entry.gradeElev, SITE_ELEV_MAX_VALUE).trim(),
      ffe:       s(entry.ffe, SITE_ELEV_MAX_VALUE).trim(),
      // pierQty (a pier count) + totalLf (linear feet) per area (Brad 2026-08-12). MANUALLY
      // entered for now (import is future). Free-text strings, same sanitize/trim as the
      // other cells (the client owns any comma/number formatting). Backward-compatible:
      // rows saved before these fields simply carry '' (absent => '').
      pierQty:   s(entry.pierQty, SITE_ELEV_MAX_VALUE).trim(),
      totalLf:   s(entry.totalLf, SITE_ELEV_MAX_VALUE).trim(),
      // columnDiameter + bearingCapacity (PSF) per area (Brad 2026-08-12). Same MANUAL
      // free-text treatment as the other cells; backward-compatible (absent => '').
      columnDiameter:  s(entry.columnDiameter, SITE_ELEV_MAX_VALUE).trim(),
      bearingCapacity: s(entry.bearingCapacity, SITE_ELEV_MAX_VALUE).trim(),
    });
  }
  return out;
}

// ---- __submittal_pull reserved structured key (Brad 2026-08-13, Stage 2) ------
// "Pull from Approved Drawings" writes the METADATA of a vision-read extraction (the
// per-area Pier Qty / Total LF land in __site_elevations rows; this key records the
// provenance + reconciliation of that pull). Stored as ONE reserved, OBJECT-valued key
// `__submittal_pull` INSIDE the `engineering` section:
//   sections.engineering.__submittal_pull = {
//     source_pdf: { name, revision, date },
//     pulled_at, requested_at, status ('requested'|'pulled'|''),
//     reconciled (bool|null),
//     extracted_total: { piers, lf },       // strings (client formats)
//     pier_schedule_total: { piers, lf },   // strings
//     delta: { piers, lf },                 // strings
//     structural_found (bool|null),         // was the Shop Drawing Info folder found
//     ffe_status ('sourced'|'pending'|''),  // FFE sourcing state
//     notes: [ "..." ]                      // provenance notes (capped list of strings)
//   }
// This is the FIFTH reserved key (alongside __crm, __submittal_prereqs, __submittal_cycles,
// __site_elevations) and rides the SAME merge: Object.assign(existing, fields) preserves it
// when a normal field save omits it. Two write paths use it: (1) the OFFICE "Pull" BUTTON
// writes a lightweight request marker { status:'requested', requested_at } — the CF Worker
// NEVER runs vision; Peter's engine does the extraction out-of-band. (2) Peter's engine (or a
// seed) writes the FULL payload { status:'pulled', reconciled, totals, ... } after the read.
// STRICTLY validated (cleanSubmittalPull below); a malformed body fails the WHOLE save closed.
// Allowed ONLY under the `engineering` section (rejected 400 anywhere else).
const PULL_KEY = '__submittal_pull';
const PULL_ALLOWED_SECTIONS = { engineering: 1 };
const PULL_MAX_STR = 300;            // a source_pdf name / status / date string cap
const PULL_MAX_NUM = 40;             // a piers/lf value (stored as a string) cap
const PULL_MAX_NOTES = 40;           // provenance notes, bounds abuse
const PULL_MAX_NOTE_LEN = 1000;      // one note line cap
const PULL_STATUSES = { requested: 1, pulled: 1, '': 1 };
const PULL_FFE_STATUSES = { sourced: 1, pending: 1, '': 1 };

// Coerce an incoming value to a strict boolean OR null (tri-state). true/false pass
// through; everything else (absent, string, number) => null. Used for reconciled /
// structural_found where "not yet known" is a meaningful, distinct state from false.
function pullTriBool(v) {
  if (v === true) return true;
  if (v === false) return false;
  return null;
}

// A {piers, lf} sub-object -> two capped STRINGS (the client owns comma/number
// formatting; we never do math). Absent/malformed => { piers:'', lf:'' }.
function pullPair(o) {
  const src = (o && typeof o === 'object' && !Array.isArray(o)) ? o : {};
  return { piers: s(src.piers, PULL_MAX_NUM), lf: s(src.lf, PULL_MAX_NUM) };
}

// Validate + normalize an incoming __submittal_pull object into a clean, bounded
// structure. Returns a SAFE object, or null if present-but-malformed (caller fails the
// whole save closed). Rules mirror cleanPrereqs' defensive posture:
//   - top-level must be a plain object (not array).
//   - status / ffe_status are constrained to their small enums (unknown => reject).
//   - reconciled / structural_found are tri-state booleans (true/false/null).
//   - source_pdf + the three totals are shape-normalized (strings only, never math).
//   - notes must be an array of strings (capped in count + length); over the cap => reject.
function cleanSubmittalPull(input) {
  if (input == null) return {};                        // absent => empty (caller preserves prior)
  if (typeof input !== 'object' || Array.isArray(input)) return null; // present but not object => reject
  const status = s(input.status, PULL_MAX_STR);
  if (!(status in PULL_STATUSES)) return null;         // unknown status => reject
  const ffe = s(input.ffe_status, PULL_MAX_STR);
  if (!(ffe in PULL_FFE_STATUSES)) return null;        // unknown ffe_status => reject
  const spIn = (input.source_pdf && typeof input.source_pdf === 'object' && !Array.isArray(input.source_pdf))
    ? input.source_pdf : {};
  let notes = [];
  if (input.notes != null) {
    if (!Array.isArray(input.notes)) return null;      // present but not an array => reject
    if (input.notes.length > PULL_MAX_NOTES) return null;
    notes = input.notes.map((n) => s(n, PULL_MAX_NOTE_LEN)).filter((n) => n !== '');
  }
  return {
    source_pdf: {
      name:     s(spIn.name, PULL_MAX_STR),
      revision: s(spIn.revision, PULL_MAX_STR),
      date:     s(spIn.date, PULL_MAX_STR),
    },
    pulled_at:    s(input.pulled_at, PULL_MAX_STR),
    requested_at: s(input.requested_at, PULL_MAX_STR),
    status: status,
    reconciled: pullTriBool(input.reconciled),
    extracted_total:     pullPair(input.extracted_total),
    pier_schedule_total: pullPair(input.pier_schedule_total),
    delta:               pullPair(input.delta),
    structural_found: pullTriBool(input.structural_found),
    ffe_status: ffe,
    notes: notes,
  };
}

// ---- __subcontract_analysis reserved structured key (Brad 2026-08-13) ---------
// The Subcontract Agreement card (Section 3, override key `contract`) gains a
// "Subcontract Analysis" SUBSECTION: a business-level review of the executed/draft
// subcontract (colored verdict, execution status, key terms, insurance + scope
// summaries, and PF's risk exposure). Historically this lived only as a legacy
// `D.analysis` block on the synced record (migrated from the standalone Subcontracts
// tool -- Indy Housing Hub only). This reserved key lets the SAME analysis be stored
// per-project as an override, and it takes precedence over the legacy `D.analysis`.
// Stored as ONE reserved, OBJECT-valued key `__subcontract_analysis` INSIDE the
// `contract` section:
//   sections.contract.__subcontract_analysis = {
//     verdict ('GREEN'|'YELLOW'|'RED'|'REVIEW'),
//     execution_status (string, bounded),
//     amount, counterparty, review_date (strings),
//     summary (string),
//     key_terms: [ { k, v }, ... ]         // bounded count + length
//     insurance_summary, scope_summary (strings),
//     risks: [ "...", ... ],               // bounded count + length
//     source (string)
//   }
// This is the SIXTH reserved key (alongside __crm, __submittal_prereqs,
// __submittal_cycles, __site_elevations, __submittal_pull) and rides the SAME merge:
// Object.assign(existing, fields) preserves it when a normal flat field save omits it,
// so editing the flat contract fields never wipes the analysis and vice-versa. The
// payload ORIGINATES FROM DOCUMENT REVIEW (untrusted): every string is length-capped +
// angle-bracket stripped here (defense-in-depth; the UI also escapes). verdict is
// ENUM-GATED. STRICTLY validated (cleanSubcontractAnalysis below); a malformed body
// fails the WHOLE save closed. Allowed ONLY under the `contract` section (400 elsewhere).
const SUBAN_KEY = '__subcontract_analysis';
const SUBAN_ALLOWED_SECTIONS = { contract: 1 };
const SUBAN_VERDICTS = { GREEN: 1, YELLOW: 1, RED: 1, REVIEW: 1 };
const SUBAN_MAX_EXEC = 200;           // execution_status string cap
const SUBAN_MAX_META = 200;           // amount / counterparty / review_date cap
const SUBAN_MAX_SUMMARY = 4000;       // summary / insurance / scope block cap
const SUBAN_MAX_SOURCE = 500;         // footer source-note cap
const SUBAN_MAX_TERMS = 40;           // key_terms rows; bounds abuse
const SUBAN_MAX_TERM_K = 200;         // a key_terms label cap
const SUBAN_MAX_TERM_V = 1000;        // a key_terms value cap
const SUBAN_MAX_RISKS = 60;           // flagged risks; bounds abuse
const SUBAN_MAX_RISK_LEN = 1000;      // one risk line cap

// Validate + normalize an incoming __subcontract_analysis object into a clean, bounded
// structure. Returns a SAFE object, or null if present-but-malformed (caller fails the
// whole save closed). Rules mirror cleanSubmittalPull's defensive posture:
//   - top-level must be a plain object (not array).
//   - verdict is ENUM-gated (upper-cased); anything outside GREEN/YELLOW/RED/REVIEW =>
//     coerced to 'REVIEW' (never rejects on a stray verdict -- the review is still valid).
//   - execution_status / amount / counterparty / review_date / summary / insurance_summary
//     / scope_summary / source are strings, length-capped + angle-bracket stripped (s()).
//   - key_terms must be an array of {k,v} objects (capped in count + length); over the
//     count cap => reject (null) so nothing is silently truncated.
//   - risks must be an array of strings (capped in count + length); over the count cap =>
//     reject. Empty risk lines are dropped.
function cleanSubcontractAnalysis(input) {
  if (input == null) return {};                        // absent => empty (caller preserves prior)
  if (typeof input !== 'object' || Array.isArray(input)) return null; // present but not object => reject
  const vraw = s(input.verdict, 20).toUpperCase();
  const verdict = (vraw in SUBAN_VERDICTS) ? vraw : 'REVIEW';   // enum-gate; stray => REVIEW
  let key_terms = [];
  if (input.key_terms != null) {
    if (!Array.isArray(input.key_terms)) return null;  // present but not an array => reject
    if (input.key_terms.length > SUBAN_MAX_TERMS) return null;
    for (const t of input.key_terms) {
      if (!t || typeof t !== 'object' || Array.isArray(t)) return null; // bad row => reject whole save
      const k = s(t.k, SUBAN_MAX_TERM_K);
      const v = s(t.v, SUBAN_MAX_TERM_V);
      if (k === '' && v === '') continue;              // drop fully-empty rows
      key_terms.push({ k, v });
    }
  }
  let risks = [];
  if (input.risks != null) {
    if (!Array.isArray(input.risks)) return null;      // present but not an array => reject
    if (input.risks.length > SUBAN_MAX_RISKS) return null;
    risks = input.risks.map((r) => s(r, SUBAN_MAX_RISK_LEN)).filter((r) => r !== '');
  }
  return {
    verdict: verdict,
    execution_status: s(input.execution_status, SUBAN_MAX_EXEC),
    amount:           s(input.amount, SUBAN_MAX_META),
    counterparty:     s(input.counterparty, SUBAN_MAX_META),
    review_date:      s(input.review_date, SUBAN_MAX_META),
    summary:          s(input.summary, SUBAN_MAX_SUMMARY),
    key_terms:        key_terms,
    insurance_summary: s(input.insurance_summary, SUBAN_MAX_SUMMARY),
    scope_summary:     s(input.scope_summary, SUBAN_MAX_SUMMARY),
    risks:            risks,
    source:           s(input.source, SUBAN_MAX_SOURCE),
  };
}

// Validate + normalize an incoming __crm object into a clean, bounded structure.
// Returns a SAFE object (possibly {}), or null if the input is present but so
// malformed it must be rejected (caller fails the whole save closed). Rules:
//   - top-level must be a plain object; each value must be a plain object with a
//     string `company` (capped) and an array `contactIds` of `^C\d+$` strings.
//   - unknown/oversized keys, non-C#### ids, and non-object firm entries are
//     DROPPED (defensive) rather than accepted verbatim.
//   - bounded on firm count + ids-per-firm; anything over the cap => reject (null)
//     so we never silently truncate a user's selection.
function cleanCrm(input) {
  if (input == null) return {};                 // absent => empty (nothing to store)
  if (typeof input !== 'object' || Array.isArray(input)) return null; // present but not an object => reject
  const out = {};
  const firmKeys = Object.keys(input);
  if (firmKeys.length > CRM_MAX_FIRMS) return null;
  for (const rawKey of firmKeys) {
    const key = s(rawKey, CRM_MAX_SUBKEY);
    if (!key) continue;
    const entry = input[rawKey];
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) return null;
    const company = s(entry.company, CRM_MAX_COMPANY);
    const idsIn = Array.isArray(entry.contactIds) ? entry.contactIds : [];
    if (idsIn.length > CRM_MAX_IDS) return null;
    const seen = {};
    const contactIds = [];
    for (const rawId of idsIn) {
      const id = String(rawId == null ? '' : rawId).trim().toUpperCase();
      if (!CRM_ID_RE.test(id)) return null;      // any bad id => reject the whole save
      if (seen[id]) continue;                    // de-dupe ids
      seen[id] = 1;
      contactIds.push(id);
    }
    // An entry with neither a company nor any ids is a cleared selection; keep it
    // as an explicit empty (so re-render shows the firm block with nothing picked).
    out[key] = { company, contactIds };
  }
  return out;
}

// The stable section keys the renderer uses for its 11 cards. A POST for any
// other section key is rejected (400) so the store can never accumulate junk
// keys. Mirrors the SECTION_LABELS map / card list in the client renderer.
const VALID_SECTIONS = {
  general: 1, pfTeam: 1, contract: 1, engineering: 1, safety: 1,
  siteReadiness: 1, equipment: 1, material: 1, qaqc: 1,
  financials: 1, closeout: 1,
  // design_professionals (Brad 2026-08-07): the General Info "Design Professionals"
  // block (the 4 engineering-firm contact cards: Ground Improvement / Geotechnical /
  // Civil / Structural) is now its OWN editable nested card. It gets its own override
  // key so its firm/contact edits persist per-project WITHOUT colliding with the
  // standalone Engineering & Design section's `engineering` key (which owns that
  // section's tracking fields). Same RBAC (financials area; field_ops blocked), same
  // string-overlay semantics as every other key here.
  design_professionals: 1,
};

const JSON_HEADERS = {
  'Content-Type': 'application/json',
  'Cache-Control': 'private, no-store',
};

function json(body, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: JSON_HEADERS });
}

// A project number: "YY-NNN" style, but we accept any short slug of
// digits/letters/hyphens so helical (25-2001) and any future scheme work. The
// number is part of the KV key, so it MUST be tightly constrained.
function cleanNum(v) {
  const str = String(v == null ? '' : v).trim();
  if (!/^[A-Za-z0-9-]{1,20}$/.test(str)) return '';
  return str;
}

function s(v, cap) {
  if (v == null) return '';
  let str = String(v);
  if (str.length > cap) str = str.slice(0, cap);
  return str.replace(/[<>]/g, ''); // strip angle brackets (UI also escapes)
}

function kvKey(num) { return KV_PREFIX + num; }

// Load the stored override object for one project, or an empty shell.
async function loadOverride(env, num) {
  const raw = await env.PF_SCHEDULE.get(kvKey(num));
  if (!raw) return { num, sections: {}, _meta: { updatedBy: null, updatedAt: null } };
  try {
    const p = JSON.parse(raw);
    const sections = (p && p.sections && typeof p.sections === 'object') ? p.sections : {};
    const _meta = (p && p._meta && typeof p._meta === 'object')
      ? p._meta : { updatedBy: null, updatedAt: null };
    return { num, sections, _meta };
  } catch {
    // Corrupt value -> treat as empty (never fabricate). A fresh save overwrites it.
    return { num, sections: {}, _meta: { updatedBy: null, updatedAt: null } };
  }
}

// Rebuild a clean field map { label: value } from arbitrary client input. Only
// string labels -> string values survive; everything is length-capped and
// angle-bracket stripped. Empty-string values are KEPT (an empty string is a
// legitimate manual override meaning "blank this field").
function cleanFields(input) {
  const out = {};
  if (!input || typeof input !== 'object') return out;
  const keys = Object.keys(input).slice(0, MAX_FIELDS_PER_SECTION);
  for (const k of keys) {
    if (k === CRM_KEY || k === PREREQ_KEY || k === CYCLES_KEY || k === SITE_ELEV_KEY || k === PULL_KEY || k === SUBAN_KEY) continue; // reserved structured keys; handled separately, never string-flattened
    const label = s(k, MAX_LABEL);
    if (!label) continue;
    out[label] = s(input[k], MAX_VALUE);
  }
  return out;
}

// ---- GET: return the stored override object for ?num=<project_number> -------
export async function onRequestGet(context) {
  const { request, env } = context;
  const denied = requireArea(context.data && context.data.session, 'financials');
  if (denied) return denied;
  try {
    const url = new URL(request.url);
    const num = cleanNum(url.searchParams.get('num'));
    if (!num) return json({ status: 'error', message: 'A valid project number is required.' }, 400);

    if (!env.PF_SCHEDULE) {
      // No KV binding: no overrides exist. This is a benign empty read (a project
      // simply has no manual overrides), so return an empty object, not an error.
      return json({ ok: true, num, sections: {}, _meta: { updatedBy: null, updatedAt: null }, fallback: true });
    }
    const rec = await loadOverride(env, num);
    return json({ ok: true, num, sections: rec.sections, _meta: rec._meta });
  } catch (err) {
    console.error('api/project-override GET error:', err);
    return json({ status: 'error', message: 'An internal error occurred.' }, 500);
  }
}

// ---- POST: merge/save one section's field overrides -------------------------
//   body: { num, section, fields:{ label:value, ... } }
// Merges `fields` into sections[section] (per-field merge: a field the client
// omits is LEFT as-is; a field set to '' is stored as a blank override). Stamps
// updatedBy (session) + updatedAt. Returns the FULL saved override object so the
// client can re-render from server truth.
export async function onRequestPost(context) {
  const { request, env } = context;
  const session = context.data && context.data.session;
  const denied = requireArea(session, 'financials');   // office only; field_ops blocked
  if (denied) return denied;
  try {
    const len = Number(request.headers.get('Content-Length') || '0');
    if (len > MAX_BODY_BYTES) return json({ status: 'error', message: 'Payload too large.' }, 413);
    const text = await request.text();
    if (text.length > MAX_BODY_BYTES) return json({ status: 'error', message: 'Payload too large.' }, 413);

    let parsed;
    try { parsed = JSON.parse(text); }
    catch { return json({ status: 'error', message: 'Invalid JSON.' }, 400); }

    const num = cleanNum(parsed && parsed.num);
    if (!num) return json({ status: 'error', message: 'A valid project number is required.' }, 400);

    const section = String((parsed && parsed.section) || '');
    if (!VALID_SECTIONS[section]) {
      return json({ status: 'error', message: 'Unknown section.' }, 400);
    }

    const fields = cleanFields(parsed && parsed.fields);

    // Reserved __crm structured key: allowed ONLY under design_professionals. If the
    // incoming fields carry a __crm object, validate it strictly. A malformed __crm
    // fails the WHOLE save closed (we never partially write a corrupt selection). A
    // __crm on any OTHER section is rejected (it has no meaning there and must not
    // pollute the store). `crmUpdate === undefined` means the request did not touch
    // __crm at all (a normal field save) -> the existing stored __crm is preserved.
    const rawFieldsObj = (parsed && parsed.fields && typeof parsed.fields === 'object') ? parsed.fields : {};
    const hasCrmInBody = Object.prototype.hasOwnProperty.call(rawFieldsObj, CRM_KEY);
    let crmUpdate; // undefined => untouched
    if (hasCrmInBody) {
      if (!CRM_ALLOWED_SECTIONS[section]) {
        return json({ status: 'error', message: 'CRM selection is not valid on this section.' }, 400);
      }
      crmUpdate = cleanCrm(rawFieldsObj[CRM_KEY]);
      if (crmUpdate === null) {
        return json({ status: 'error', message: 'Invalid CRM selection; nothing was saved.' }, 400);
      }
    }

    // Reserved __submittal_prereqs structured key (Brad 2026-08-12): the GC prerequisites
    // checklist on the Engineering & Design > PF Design Submittal subsection. Allowed ONLY
    // under `engineering`. Same posture as __crm: absent => untouched (preserve prior),
    // present => strictly validated, malformed => reject the WHOLE save closed. A checklist
    // save from the client sends this key WITHOUT the flat engineering fields, so cleanFields
    // yields {} and only the checklist is replaced; a normal engineering field save omits
    // this key so the stored checklist is preserved by the merge below.
    const hasPrereqInBody = Object.prototype.hasOwnProperty.call(rawFieldsObj, PREREQ_KEY);
    let prereqUpdate; // undefined => untouched
    if (hasPrereqInBody) {
      if (!PREREQ_ALLOWED_SECTIONS[section]) {
        return json({ status: 'error', message: 'Submittal prerequisites are not valid on this section.' }, 400);
      }
      prereqUpdate = cleanPrereqs(rawFieldsObj[PREREQ_KEY]);
      if (prereqUpdate === null) {
        return json({ status: 'error', message: 'Invalid submittal prerequisites; nothing was saved.' }, 400);
      }
    }

    // Reserved __submittal_cycles structured key (Brad 2026-08-12, Stage 2): the PF
    // Design Submittal revision-cycle array (Original + Rev1/Rev2/...) on the Engineering
    // & Design > PF Design Submittal subsection. Allowed ONLY under `engineering`. Same
    // posture as __submittal_prereqs: absent => untouched (preserve prior), present =>
    // strictly validated, malformed => reject the WHOLE save closed. A cycles save from
    // the client sends this key WITHOUT the flat engineering fields, so cleanFields yields
    // {} and only the cycles array is replaced; a normal engineering field save omits this
    // key so the stored cycles are preserved by the merge below.
    const hasCyclesInBody = Object.prototype.hasOwnProperty.call(rawFieldsObj, CYCLES_KEY);
    let cyclesUpdate; // undefined => untouched
    if (hasCyclesInBody) {
      if (!CYCLES_ALLOWED_SECTIONS[section]) {
        return json({ status: 'error', message: 'Submittal cycles are not valid on this section.' }, 400);
      }
      cyclesUpdate = cleanCycles(rawFieldsObj[CYCLES_KEY]);
      if (cyclesUpdate === null) {
        return json({ status: 'error', message: 'Invalid submittal cycles; nothing was saved.' }, 400);
      }
    }

    // Reserved __site_elevations structured key (Brad 2026-08-12): the Site Grade
    // Elevations subsection array on the Engineering & Design section (per-area site grade
    // + FFE capture). Allowed ONLY under `engineering`. Same posture as __submittal_cycles:
    // absent => untouched (preserve prior), present => strictly validated, malformed =>
    // reject the WHOLE save closed. A site-elevations save from the client sends this key
    // WITHOUT the flat engineering fields, so cleanFields yields {} and only the array is
    // replaced; a normal engineering field save omits this key so the stored array is
    // preserved by the merge below.
    const hasSiteElevInBody = Object.prototype.hasOwnProperty.call(rawFieldsObj, SITE_ELEV_KEY);
    let siteElevUpdate; // undefined => untouched
    if (hasSiteElevInBody) {
      if (!SITE_ELEV_ALLOWED_SECTIONS[section]) {
        return json({ status: 'error', message: 'Site grade elevations are not valid on this section.' }, 400);
      }
      siteElevUpdate = cleanSiteElevations(rawFieldsObj[SITE_ELEV_KEY]);
      if (siteElevUpdate === null) {
        return json({ status: 'error', message: 'Invalid site grade elevations; nothing was saved.' }, 400);
      }
    }

    // Reserved __submittal_pull structured key (Brad 2026-08-13, Stage 2): the "Pull from
    // Approved Drawings" provenance/reconciliation metadata on the Engineering & Design
    // section. Allowed ONLY under `engineering`. Same posture as the other reserved keys:
    // absent => untouched (preserve prior), present => strictly validated, malformed =>
    // reject the WHOLE save closed. Two writers use it — the office Pull BUTTON (a small
    // request marker) and Peter's out-of-band engine (the full payload). Both send this key
    // WITHOUT the flat engineering fields, so cleanFields yields {} and only this key is
    // replaced; a normal engineering field save omits it so the stored pull is preserved.
    const hasPullInBody = Object.prototype.hasOwnProperty.call(rawFieldsObj, PULL_KEY);
    let pullUpdate; // undefined => untouched
    if (hasPullInBody) {
      if (!PULL_ALLOWED_SECTIONS[section]) {
        return json({ status: 'error', message: 'Submittal pull is not valid on this section.' }, 400);
      }
      pullUpdate = cleanSubmittalPull(rawFieldsObj[PULL_KEY]);
      if (pullUpdate === null) {
        return json({ status: 'error', message: 'Invalid submittal pull metadata; nothing was saved.' }, 400);
      }
    }

    // Reserved __subcontract_analysis structured key (Brad 2026-08-13): the Subcontract
    // Analysis subsection on the Subcontract Agreement card (Section 3). Allowed ONLY under
    // `contract`. Same posture as the other reserved keys: absent => untouched (preserve
    // prior), present => strictly validated, malformed => reject the WHOLE save closed. The
    // writer (Peter's review engine or a seed) sends this key WITHOUT the flat contract
    // fields, so cleanFields yields {} and only this key is replaced; a normal contract field
    // save omits it so the stored analysis is preserved by the merge below.
    const hasSubanInBody = Object.prototype.hasOwnProperty.call(rawFieldsObj, SUBAN_KEY);
    let subanUpdate; // undefined => untouched
    if (hasSubanInBody) {
      if (!SUBAN_ALLOWED_SECTIONS[section]) {
        return json({ status: 'error', message: 'Subcontract analysis is not valid on this section.' }, 400);
      }
      subanUpdate = cleanSubcontractAnalysis(rawFieldsObj[SUBAN_KEY]);
      if (subanUpdate === null) {
        return json({ status: 'error', message: 'Invalid subcontract analysis; nothing was saved.' }, 400);
      }
    }

    // FAIL CLOSED: no KV -> we cannot persist. Do NOT report success.
    if (!env.PF_SCHEDULE) {
      return json({ status: 'error',
        message: 'Persistence unavailable: KV binding PF_SCHEDULE is not configured on this deployment. Your edit was NOT saved.' }, 503);
    }

    const rec = await loadOverride(env, num);

    // Per-field merge into the section (KV read-modify-write; single-writer
    // acceptable for a project record edited by one office user at a time -- same
    // known limitation as daily-report; a D1 migration is the durable fix).
    const existing = (rec.sections[section] && typeof rec.sections[section] === 'object')
      ? rec.sections[section] : {};
    // Carry forward any existing structured __crm; cleanFields already stripped it
    // from `fields`, so a normal string-field save never disturbs it.
    const prevCrm = (existing[CRM_KEY] && typeof existing[CRM_KEY] === 'object' && !Array.isArray(existing[CRM_KEY]))
      ? existing[CRM_KEY] : undefined;
    // Carry forward any existing structured __submittal_prereqs the same way.
    const prevPrereq = (existing[PREREQ_KEY] && typeof existing[PREREQ_KEY] === 'object' && !Array.isArray(existing[PREREQ_KEY]))
      ? existing[PREREQ_KEY] : undefined;
    // Carry forward any existing structured __submittal_cycles (an ARRAY, unlike the two
    // object keys above -- so the type guard checks Array.isArray, not the object shape).
    const prevCycles = Array.isArray(existing[CYCLES_KEY]) ? existing[CYCLES_KEY] : undefined;
    // Carry forward any existing structured __site_elevations (also an ARRAY).
    const prevSiteElev = Array.isArray(existing[SITE_ELEV_KEY]) ? existing[SITE_ELEV_KEY] : undefined;
    // Carry forward any existing structured __submittal_pull (an OBJECT, like __crm).
    const prevPull = (existing[PULL_KEY] && typeof existing[PULL_KEY] === 'object' && !Array.isArray(existing[PULL_KEY]))
      ? existing[PULL_KEY] : undefined;
    // Carry forward any existing structured __subcontract_analysis (an OBJECT, like __crm).
    const prevSuban = (existing[SUBAN_KEY] && typeof existing[SUBAN_KEY] === 'object' && !Array.isArray(existing[SUBAN_KEY]))
      ? existing[SUBAN_KEY] : undefined;
    const merged = Object.assign({}, existing, fields);
    // Whole-object replace of __crm when the request supplied one (the client sends
    // the complete per-firm selection each time); otherwise preserve the prior value.
    if (crmUpdate !== undefined) merged[CRM_KEY] = crmUpdate;
    else if (prevCrm !== undefined) merged[CRM_KEY] = prevCrm;
    else delete merged[CRM_KEY]; // never leave a stray/non-object __crm behind
    // Same whole-object replace/preserve for __submittal_prereqs (the client sends the
    // complete 7-item checklist each save); otherwise preserve the prior value.
    if (prereqUpdate !== undefined) merged[PREREQ_KEY] = prereqUpdate;
    else if (prevPrereq !== undefined) merged[PREREQ_KEY] = prevPrereq;
    else delete merged[PREREQ_KEY]; // never leave a stray/non-object key behind
    // Same whole-object (array) replace/preserve for __submittal_cycles (the client sends
    // the COMPLETE Original+Rev1+Rev2... array each save); otherwise preserve the prior.
    if (cyclesUpdate !== undefined) merged[CYCLES_KEY] = cyclesUpdate;
    else if (prevCycles !== undefined) merged[CYCLES_KEY] = prevCycles;
    else delete merged[CYCLES_KEY]; // never leave a stray/non-array key behind
    // Same whole-array replace/preserve for __site_elevations (the client sends the
    // COMPLETE areas array each save); otherwise preserve the prior.
    if (siteElevUpdate !== undefined) merged[SITE_ELEV_KEY] = siteElevUpdate;
    else if (prevSiteElev !== undefined) merged[SITE_ELEV_KEY] = prevSiteElev;
    else delete merged[SITE_ELEV_KEY]; // never leave a stray/non-array key behind
    // Same whole-object replace/preserve for __submittal_pull (the writer sends the COMPLETE
    // metadata object each save); otherwise preserve the prior.
    if (pullUpdate !== undefined) merged[PULL_KEY] = pullUpdate;
    else if (prevPull !== undefined) merged[PULL_KEY] = prevPull;
    else delete merged[PULL_KEY]; // never leave a stray/non-object key behind
    // Same whole-object replace/preserve for __subcontract_analysis (the writer sends the
    // COMPLETE analysis object each save); otherwise preserve the prior.
    if (subanUpdate !== undefined) merged[SUBAN_KEY] = subanUpdate;
    else if (prevSuban !== undefined) merged[SUBAN_KEY] = prevSuban;
    else delete merged[SUBAN_KEY]; // never leave a stray/non-object key behind
    rec.sections[section] = merged;

    // Bound the number of sections (defense against a crafted flood of junk keys;
    // VALID_SECTIONS already limits keys to the 11, so this can only trip on abuse).
    if (Object.keys(rec.sections).length > MAX_TOTAL_SECTIONS) {
      return json({ status: 'error', message: 'Too many sections.' }, 413);
    }

    const who = (session && (session.name || session.uid)) ? s(session.name || session.uid, MAX_LABEL) : 'unknown';
    const nowIso = new Date().toISOString();
    rec._meta = { updatedBy: who, updatedAt: nowIso };

    const toStore = { version: 1, num: rec.num, sections: rec.sections, _meta: rec._meta };
    await env.PF_SCHEDULE.put(kvKey(num), JSON.stringify(toStore));

    return json({ ok: true, saved: true, num, section, sections: rec.sections, _meta: rec._meta });
  } catch (err) {
    console.error('api/project-override POST error:', err);
    return json({ status: 'error', message: 'An internal error occurred.' }, 500);
  }
}
